{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '진짜 내 목소리'와 '여기서만 괜찮은 목소리'의 차이를 물었을 때, 내담자가 자신의 필요와 감정을 신뢰하지 못하는 근본 원인이 유기/불안정 스키마에 있음. 어린 시절 반복된 버림 경험이 '내 목소리(필요)는 위험하다'는 전제를 만들었음."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '진짜 내 목소리인지 모르겠다'고 말한 것은, 필요를 표현하면 결함 있는 사람으로 거절당한다는 단절/거절 도메인 믿음과 직접 연결됨. 공개 대화에서 '필요로 하는 것 자체가 잘못인 것 같았어요'라고 명시함."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/situations/1"],
      "relevance": "'진짜 내 목소리'를 의심하는 것은 '내가 사랑하는 사람은 결국 나를 떠날 것이다'는 핵심 믿음이 작동하기 때문. 공개 대화에서 '이러니까 다 떠나는 거야'라는 목소리가 작은 목소리를 덮는다고 진술함. 상황 사례 1의 '너무 힘들게 한다'가 이 믿음을 강화한 구체적 증거."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": [],
      "relevance": "'상대가 떠날 조짐이 없는지 항상 살펴야 한다'는 규칙이 내담자로 하여금 자신의 내면 신호(작은 목소리)를 신뢰하지 못하게 함. 규칙이 작동할수록 외부 확인에 의존하게 되어 '내 목소리'의 정체를 구분할 수 없게 됨."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": [],
      "relevance": "'확인을 멈추고 마음을 놓아버리면 상대가 사라질 것'이라는 부정적 가정은, 상담장에서 '여기서는 작게 있어볼 수 있을 것 같아요'라고 말한 뒤에도 곧바로 '여기서만 괜찮은 건지 모르겠다'고 후퇴하게 만드는 기제. 마음을 놓는 것 자체가 위험하므로 내 목소리를 신뢰할 수 없음."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": [],
      "relevance": "상담사가 '진짜 내 목소리와 여기서만 괜찮은 목소리가 어떻게 다른가'라고 묻자, 내담자는 그 차이를 스스로 확인하기보다 상담사에게 다시 확인을 구하는 양상을 보임. 이는 연인에게 '아니'라는 답을 들어도 몇 번씩 다시 묻는 대처 전략이 상담 관계로도 전이된 것."
    }
  ]
}

